-- Tillgg till WPS.L.quest: godkanda omgngar ur translation/out/,
-- sammanfogade av tools/merge-translation.py. Gr inte handandringar hr:
-- nsta krning regenererar filen, gamla rader rrs aldrig om.
-- Flt t,o,d,p,c; tomt flt = ingen nyckel (addonet byter bara flt som finns).
-- l-rader (sprarrader i trakern) saknas: tckningsbegrnsning, se PIPELINE.md;
-- sparraderna frblir engelska till vidare, oskadligt.
local _, WPS = ...
local LQ = WPS.L.quest

local extra = {
[185]={t="Tigerbehärskning", o="Ajeck Rouack från Nesingwarys expedition vill att du dödar 10 unga strypetörnstigrar.", d="När jag bara var en ung flicka tränade min far mig i konsten att jaga tigrar.$b$bDu kommer att finna de unga kattdjuren mycket lättare att spåra och dräpa. Av den anledningen börjar vi enkelt. Man kan ofta finna unga tigrar nära expeditionslägret.$b$bTesta dina spårningsfärdigheter och se om du kan jaga rätt på några av bestarna."}, -- quests-batch-08-sv
[190]={t="Pantermästerskap", o="Sir S. J. Erlgadin från Nesingwarys expedition vill att du dödar 10 unga pantrar.", d="Om du vill vara en del av jakten med den här expertgrupp som Hemet har sammanställt, måste du bevisa att du är en skicklig panterjägare. Vi börjar enkelt -- oroa dig inte. Låt oss se dig döda 10 unga pantrar för att börja.$b$bAtt spåra upp dem är bara halva utmaningen..."}, -- quests-batch-13-sv
[194]={t="Raptormästerskap", o="Hemet Nesingwary vill att du dödar 10 Strypetörnsraptorer.", d="Så du tror att dina jaktkunskaper är i toppform? Jag kan sätta dem på prov på ett ögonblick. Bege dig ut i djungeln och döda 10 Strypetörnsraptorer. Vi får se hur stor av en storviltjägare du egentligen är.$b$bOch nej, jag tänker inte berätta var du kan hitta dem! Att lokalisera bestarna är halva utmaningen."}, -- quests-batch-11-sv
[197]={t="Raptormästerskap", o="Hemet Nesingwary vill att du dödar Tethis, en svårfångad och farlig raptor i Strypetörnsdalen.", d="Eftersom du visat dig vara så driven i djungeln, låt mig berätta om en vild raptor som till och med jag har misslyckats med att döda. Ajeck här kallar denna sluga raptor för Tethis.$b$bOm du vill bevisa att du är en sann mästare, döda Tethis och ta med mig hans klo. Det vore en bedrift som ingen annan storviltjägare har lyckats med."}, -- quests-batch-08-sv
[208]={t="Storviltjägare", o="Hemet Nesingwary vill att du hämtar huvudet av King Bangalash, den store vita tigern.", d="$n, du är en jägare värdig vårt sällskap. Från Lordaerons slagfält till den djupaste djungeln har jag sällan bevittnat sådan skicklighet med vapen som du har uppvisat.$b$bDu har dödat den vildsinta Sin'Dall, den svårfångade Bag'thera och den förrädiska Tethis. Men det sanna priset är huvudet av King Bangalash. Den vita tigern är anledningen till att jag är här. Jag har haft siktet inställt på honom under en lång tid nu. Döda King Bangalash så är din jaktförmåga bevisad vara oöverträffad."}, -- quests-batch-11-sv
[507]={t="Lord Aliden Perenolde", o="Döda lord Aliden Perenolde och fråga hans mätress, Elysa, om Tarethas hängsmycke.", d="Det är tydligt att Perenolde måste dödas, hans vidrighet avlägsnas från världen. Hans herrgård ligger en bit norrut härifrån, vid stränderna av Lordameresjön. Gör din plikt, $n, hämta sedan hängsmycket som krigsherren önskar och återvänd hit."}, -- quests-batch-06-sv
[518]={t="Viljans krona", o="Döda 14 Crushridge Maulers åt Melisara i Tarrens kvarn.", d="Mug'Thol och hans Crushridge-ograr har tagit över Alteracruinerna. Det kommer att bli svårt att utdela något allvarligt straff till honom utan att minska ograrnas antal.$b$bNär vi har försvagat dem, går vi vidare.$b$bFörstått? Bra. Gå nu."}, -- quests-batch-03-sv
[533]={t="Infiltration", o="Hämta information om Gol'dirs vistelseort till Krusk i Tarrens kvarn.", d="Äntligen börjar vi höra rykten och få ledtrådar om var Gol'dir befinner sig. Människorna har flyttat runt honom, men vi smalnar av vår sökning och fokuserar på det stora Syndikatlägret precis norr om här.$b$bGå dit, $n, och ta med dig all information du kan komma över."}, -- quests-batch-08-sv
[544]={p="Tjuvarna flydde från Understaden till Dalaran, och dessa trollkarlar satte dem i karantän i Lordameres interneringsläger."}, -- quests-batch-08-sv
[550]={t="Slaget vid Hillsbrad", o="Lämna Darthalias förseglade rekommendationsbrev till Varimathras i Understaden.", d="Eftersom du stred med sådan tapperhet och uthållighet i slaget vid Hillsbrad har jag skrivit detta rekommendationsbrev, som hyllar dina heroiska insatser i strid så att den högsta ledningen kan erkänna dem.$b$bLämna detta förseglade rekommendationsbrev till Varimathras i Understaden. Gå med stolthet, $c."}, -- quests-batch-09-sv
[552]={t="Helculars hämnd", o="Hämta Helculars stav från yetin och ta med den till novis Thaivand i Tarren Mill.", d="Mästare Helcular var nästan färdig med sin förvandling till en Lich när en lynchmobb av människor upptäckte hans rituallya i kullarna och brutalt dödade honom. För att göra saken värre begravde de hans lik på kyrkogården i Sydstrand.$b$bEtt sådant förakt för den store trollkarlen är oacceptabelt. Som hans lärling ska jag se till att hämndens regn faller över staden Sydstrand.$b$bVi behöver först Helculars stav. Yetier tog över hans rituallya. Utan tvekan har ett av odjuren den."}, -- quests-batch-10-sv
[553]={t="Helculars hämnd", o="Ladda Helculars stav med krafterna från Azels flamma, Verazs flamma och Uzels flamma.$b$bSätt ner den laddade staven i Helculars grav i Sydstrand.", d="Här, ta Helculars stav. Du kommer att behöva den.$b$bHelcular skapade tre ceremoniella bål som en del av sin mäktigaste besvärjelse. Azels flamma och Verazs flamma finns i Förbergsgrottorna. Uzels flamma finns i en grotta ovanför grottorna, längre norrut i bergen.$b$bHelculars stav måste laddas från var och en av de tre flammorna. När ritualen är fullbordad, sätt ner staven i Helculars grav i Sydstrand, den hårt bevakade människostaden i söder. Hämnen ska bli vår!"}, -- quests-batch-04-sv
[556]={t="Stentokens", o="Lämna 10 slitna stentokens till Keeper Bel'varil i Tarrens kvarn.", d="En anmärkningsvärd talang hos magikerna i Dalaran är deras bekantskap med elementaler: kraftfulla varelser från andra dimensioner. Magikerna använder magiska tokens som ett sätt att kontrollera dessa elementaler. Magus Voidglare skulle vilja ha några av dessa tokens för att studera dem.$B$BGå in i Dalaranmagikernas territorier, väster om Hillsbrad, och samla in tokens.$B$BDu kan hitta tokens hos vilken medborgare i Dalaran som helst, men jag föreslår att du jagar vid interneringslägret. Det är säkrare än Dalaran självt."}, -- quests-batch-04-sv
[568]={t="Försvaret av Grom'gol", o="Befälhavare Aggro'gosh vid Grom'gols basläger vill att du dödar 15 piskvansraptorer.", d="Throm'ka, $c!$b$bDin ankomst till Grom'gol är sannerligen i rätt tid. Som befälhavare för krigsledarens basläger här i djungeln är jag bunden av heder att garantera säkerheten för alla medlemmar av Horden. Vårt uppdrag att tillhandahålla en säker försörjningskedja till Stonard hindras av några av de lokala invånarna.$b$bJag sätter dig ansvarig för att gallra ut raptorpopulationen utanför Grom'gol. När du har gjort betydande framsteg, rapportera tillbaka till mig för omplacering."}, -- quests-batch-01-sv
[570]={t="Mok'thardins förtrollning", o="Fjärrsiare Mok'thardin vid Grom'gol-baslägret vill ha 8 Shadowmaw-klor och en fläckfri tigerrandshuggtand.", d="Djungelmagins kraft måste förstås och sedan tämjas av Horden. Mina ritualer har varit framgångsrika hittills. Jag kan kasta mycket kraftfulla förtrollningar. För dig, tappre $c, ska jag skapa ett sannerligen speciellt föremål.$b$bTa med mig några klor från Shadowmaw-pantrar tillsammans med en tigerrandshuggtand. Inte vilken tand som helst duger. Den måste vara i fläckfritt skick.$b$bBestarna lurar i hela djungeln, men du kommer att hitta några i närheten, precis över floden från Mizjah-ruinerna i sydost."}, -- quests-batch-06-sv
[571]={t="Mok'thardins förtrollning", o="För med dig en åldrad gorillsena till fjärrseende Mok'thardin i Grom'gol.", d="Det jag behöver av dig nu kommer att vara mycket svårt att få tag på.$b$bFör att hålla alla dessa fjädrar, klor och den fläckfria beten på plats behöver jag ett magiskt fäste. Endast en åldrad gorillsena kommer att fungera.$b$bDu kan bara hitta en sådan på en äldre Mistvale-gorilla. De är kända för att söka föda öster om Bytesbukten.$b$bSenan måste vara perfekt. Det kan krävas en hel del dödande innan du hittar precis det jag behöver, men det kommer att vara väl värt jakten."}, -- quests-batch-05-sv
[573]={t="Mok'thardins förtrollning", o="Fjärrsiare Mok'thardin i Grom'gol behöver heligt källvatten. Han vill också att du dödar 10 nagaupptäckare.", d="Det finns bara en sista ingrediens kvar för att slutföra förtrollningen.$b$bI söder, mot västkusten, högt ovanför klipporna, ligger en helig källa. Denna källa är föremål för stora konflikter mellan religiösa och mystiska lärda. Varje ras i Azeroth hävdar att källvattnet gjordes gudomligt för just deras folk.$b$bMin sista begäran till dig: hämta heligt källvatten till mig. Var varnad. En expedition av nagaupptäckare har avancerat mot källan. De måste också tas om hand."}, -- quests-batch-12-sv
[581]={t="Jakten på Yenniku", o="Lämna 9 Bloodscalp-betar till Nimboya vid Grom'gol-baslägret.", d="En undergång, det finns. En undergång över min hövdings yngsta son, Yenniku. Enligt vår folks sed gavs han till Gurubashi-trollen i Zul'Gurub, men efter att min stam, Mörkspjutsstammen, lämnade med orchen Thrall, gick stackars Yenniku förlorad för oss. Jag skickades från fjärran Orgrimmar, tillbaka till Strypetörnsdalen, för att leta efter min hövdings son.$B$BAnd jag tror att Bloodscalp-stammen har honom.$B$BOm du vill hjälpa mig, jaga då Bloodscalps. Du kan finna dem i norr. Samla deras betar och återvänd till mig."}, -- quests-batch-05-sv
[586]={t="Samtal med Gan'zulah", o="Döda 8 Skullsplitter-jägare, 6 Skullsplitter-huvudjägare och 4 Skullsplitter-berserker.$B$BFör Ana'theks sönderslagna rustning till den bubblande kitteln i Grom'gol-baslägret.", d="<Gan'zulahs huvud talar.>$B$BFörbanna dig! Och förbanna dina förfäder!!$B$BEndast blod och hämnd kan kyla min vrede, så om det är din önskan ... gör detta:$B$BKasta dig in i hjärtat av Skullsplitternas land österut. Dräp de vildaste bland dem, och om du överlever ... krossar du dig mot deras hövding, Ana'thek den Grymme. Hah! För mig hans sönderslagna rustning om du kan!$B$BMå han riva av dig lemmarna och lämna dig att ruttna och ätas av asätare."}, -- quests-batch-07-sv
[595]={t="Blodseglens bukanjärer", o="Förste styrman Crazz vill att du undersöker viken norr om Bytesbukten.", d="Du verkar verkligen ivrig att arbeta, kamrat. Vet inte varför någon landkärring till $r $c erbjuder hjälp till Blackwater-plundrarna, men jag tänker inte neka dig.$b$bVårt skepp har precis lagt till här i Bytesbukten och ryktet säger att våra rivaler – dessa förbannade, smutsiga Blodseglens bukanjärer – har siktats över hela södra Strypetörnsdalen.$b$bAlla grabbarna är för upptagna med att dricka grog och leta efter damer! Vad jag behöver är en spanare.$b$bUndersök viken precis norr om Bytesbukten längs Vilda kusten och se vad du hittar."}, -- quests-batch-12-sv
[596]={t="Blodiga benhalsband", o="För med dig 25 blodiga benhalsband till Kin'weelay vid Grom'gol-baslägret.", d="Jag skickades till Grom'gol för att hjälpa Nimboya i hans sökande, men... jag har också mina skäl till att vara här.$B$BBlodskalpstammen är vår stams fiende. Att samla troféer från våra fiender ger oss makt över dem. Du kan hjälpa vår stam genom att jaga våra fiender.$B$BDe bor i norr. Dräp Blodskalptroll och ta deras blodiga benhalsband. Samla många, så kommer din belöning att bli stor."}, -- quests-batch-09-sv
[605]={t="Sjungande blå skärvor", o="Lämna 10 sjungande kristallskärvor till Crank Fizzlebub.", d="De sjungande kristallerna är unika för Strypetörnsdalen och är mycket värdefulla för vissa parter. Jag kan sälja dessa kristaller, men den förbannade Äventyrsbolaget gör det svårt för en ärlig entreprenör som jag att samla in några!$B$BJag skulle vilja anställa dig.$B$BBasilisker i Strypetörnsdalen äter kristallen. Detta ger dem deras härdade hud, och ibland kan kristaller av anständig kvalitet skördas från den.$B$BDu kan få dem från vilken basilisk som helst, men de mindre elaka finns längs kusterna söder om Zul'Kunda, i norr."}, -- quests-batch-05-sv
[606]={t="Skrämma Shaky", o="Ta 5 Mistvale-inälvor till \"Shaky\" Phillipe i Bytesbukten.", d="Om det är en sak jag inte kan stå ut med, så är det folk som inte betalar sina spelskulder! Och det finns många som är skyldiga mig. Tror du att du kan hjälpa mig att driva in dem?$B$BFörst har vi \"Shaky\" Phillipe nere vid dockorna. Han är skyldig mig gott och väl efter förra veckans spel och jag vill ha min rätt! Men för att få den måste vi skrämma honom.$B$BGå ut ur staden och jaga äldre Mistvale-gorillor. Hitta ett fint urval av inälvor och ta dem sedan till Shaky. Låt honom inte ana att de kommer från ett djur; låt honom tro det värsta."}, -- quests-batch-06-sv
[629]={t="Det vidriga revet", o="Lämna ett tavelskärva till Kin'weelay vid Grom'gol-baslägret.", d="För länge sedan sänkte en stor jordbävning en gammal trollstad under vattnen vid Vilda kusten i nordväst. Vi kallar den platsen för Det vidriga revet, för murlocs bor nu i stadens ruiner och attackerar alla som kommer nära.$B$BDet finns en gammal tavla bland dessa ruiner som berättar den forna sagan om Gri'lek, en hjälte i trollens legender. Sagan är helig för Mörkspjutstrollen, och även om tavlan är för stor för att flyttas, vill jag ha en skärva av den för att viga den i vårt nya hem i Orgrimmar."}, -- quests-batch-05-sv
[635]={t="Kristallen i bergen", o="Hitta kristallen från din vision.", d="Denna skärva pulserar när du håller i den...$B$BDu känner en känsla av bön från skärvan, som om någon försöker kommunicera, någon som desperat behöver din hjälp.$B$BEn vision dyker upp i ditt sinne - av de norra bergen i Arathi, och av en strålande kristall som sticker upp ur jorden där.$B$BDu känner dig dragen till den platsen."}, -- quests-batch-02-sv
[639]={t="Stroms sigill", o="Hämta Stroms sigill till Zengu i Hammarfall.", d="I forntiden stred trollen mot Arathors imperium och vår mest kapabla motståndare, lord Ignaeus av Strom, kallad Trollbane. Han red i strid med Trol'kalar -- trolldräparen, på deras forntida tungmål.$b$bMen nu är Trollbanes söner försvagade och deras fäste lagt i ruiner.$b$bSvärdet skyddas av flera sigill som fördelades mellan de överlevande från Stromgarde, och vi måste återta dem.$b$bDet första togs av Syndikatet; en av deras män i Stromgarde borde ha det."}, -- quests-batch-14-sv
[656]={t="Frammaning av prinsessan", o="Gå till Shards of Myzrael, frammana henne och besegra henne.$B$BSamla hennes Eldritch Shackles och bind dem vid Shards of Myzrael.", d="Du måste besegra Myzrael innan hon växer i styrka. Om du inte gör det, kommer hon att utmana sina fångvaktare så snart hon har samlat tillräckligt med kraft! Det finns vissa som tror att de kan kontrollera henne, men om hon kan kontrolleras, varför kedjade jättarna då fast henne från första början??$B$BGalen logik, va?$B$BFör att besegra henne, frammana henne vid Shards of Myzrael där du först talade med henne. Besegra henne och samla hennes Eldritch Shackles, och bind dem sedan vid Shards of Myzrael.$B$BGör det, så kommer hon återigen att bli fångad."}, -- quests-batch-11-sv
[671]={t="Vidrig magi", o="Hämta 10 blodstensamuletter till Tor'gan i Hammarfall.", d="Jag har känt något märkligt i luften... en känsla som sjuder i mitt blod. Jag hade mina misstankar. Jag gav mig av för att finna källan till mitt obehag och upptäckte i väster, vid Northfold Manor, kvarlevor av demonisk frammaning. När jag kom nära började mitt blod koka och vreden inom mig växte.$b$bPå marken fick jag syn på en amulett av blodsten, som används för att hjälpa till vid demonisk frammaning. Den jag fann var dock tömd. Jag behöver en annan att undersöka, men jag vågar inte återvända till herrgården. Kan du hämta några åt mig?"}, -- quests-batch-13-sv
[672]={t="Väcka andar", o="Samla 10 Highland Raptor-ögon från Highland Striders och Highland Thrashers till Tor'gan i Hammarfall.", d="Vi försökte få honom att komma till rätta, muntra upp honom genom att berätta historier om vår mäktiga stad Orgrimmar i Kalimdor, men inget hjälpte.$b$bBerättelser om vår unge krigsherre, Thrall, som bär Orgrims rustning och hammare... men, kanske... Kanske! En demonstration av vår nyfunna schamanistiska magi skulle ge honom nytt hopp. Det är värt ett försök!$b$bEtt litet föremål vi skulle kunna tillverka åt honom, ja... Hämta några raptorögon till mig, så ska jag se vad jag kan göra."}, -- quests-batch-03-sv
[673]={t="Orena magier", o="Hämta Marez Cowls blodstensglob och lämna den till Tor'gan i Hammarfall.", d="Jag är helt övertygad om att en mäktig häxmästare håller till inom Stromgardes murar. Med hjälp av en arkan magisk relik har denna häxmästare då och då frammanat fruktansvärda demoner i stora mängder. Vi måste avlägsna källan till hans energi.$b$bHitta häxmästaren och döda honom. För med dig det magiska föremål du finner på honom, så ska jag vidta åtgärder för att förstöra det och se till att dess kraft inte längre används för att besudla detta land."}, -- quests-batch-11-sv
[676]={t="Hammaren kan falla", o="Döda 8 Boulderfist-ograr och 10 Boulderfist-ordningsvakter, och leta sedan upp Drum Fel i Hammerfall-utposten i Arathihöglandet.", d="Vecklingar... varenda en. Du, $c, vad glor du på? Tror du att du är något speciellt, va? Varför bevisar du det inte?$B$BHammerfall-utposten i Arathi är under attack. Om vi inte skickar hjälp snart är deras undergång nära.$B$BMen innan du rusar iväg vill du kanske testa dina färdigheter först. Nordost om Stromgarde i Arathi finns en ogerkulle där Boulderfist-stammen bor. När du kan hantera ograrna och ordningsvakterna där, rapportera då till Drum Fel i Hammerfall."}, -- quests-batch-10-sv
[679]={t="Kallelse till vapen", o="Döda 15 Boulderfist-schamaner och 10 Boulderfist-herrar och återvänd till Drum Fel i utposten Hammerfall.", d="Bestens huvud är redo att huggas av... med stor kraft, $n. Du har visat alla tecken på att du kan hjälpa oss med detta sista mäktiga slag. Ledarna för dessa attacker har gjort sitt läger i ruinerna av Stromgarde, en tydlig symbol för människans svaghet.$B$BHitta och dräp dessa Boulderfist-herrar och deras hantlangare till schamaner som försöker driva oss från dessa marker."}, -- quests-batch-06-sv
[680]={t="Det verkliga hotet", o="Dräp Or'Kalar och för hans huvud till Korin Fel i utposten Hammarfall.", d="Du tjänar min make väl, $c, men han vet inte varför Hammarfall är under attack.$B$BOr'Kalar, Mug'thols bricka i Stromgarde, hyser ett intensivt hat mot min make och önskar inget hellre än min makes död för att han besegrade honom för många år sedan.$B$BMina varsel säger mig att Or'Kalar har lagt en fälla för min make, så jag har dolt tecknen på ogerns närvaro för honom.$B$BMin make kommer att rusa iväg dåraktigt om han får reda på var ogern befinner sig, så jag ber om din hjälp att dräpa varelsen."}, -- quests-batch-12-sv
[687]={t="Theldurin den förlorade", o="Hitta Theldurin den förlorade.", d="Theldurin den förlorade var en gång medlem i vår orden, Skymningshammaren. Men han förlorade förståndet och föraktade våra läror. Och innan han flydde från oss stal han Myzraels rulle! Vi kunde inte fånga honom, men rykten säger att han gömmer sig i Ofärdsmarken, jattrande och galen.$B$BFör att föra Lady tillbaka till oss måste du hitta rullen. Och för att göra det måste du hitta Theldurin."}, -- quests-batch-02-sv
[698]={t="Brist på överskott", o="Lämna 8 oförberedda sågtandssidor till Tok'Kar i Sorgeträsket.", d="Jag arbetar med att samla ihop förnödenheter till vår utpost nära stranden i öster – Tok'kar gör vad han kan, men mellan vaktskiften och matlagning till sina soldater finns det inte mycket tid kvar på dagen.$B$BDe tycker om att tillaga sågtandskött när de kan, men jag har inte haft tid att skicka dem en ny leverans. Skulle du vilja hjälpa dem?$B$BDe unga sågtänderna är inte lika goda som de äldre, så håll dig borta från dem; låt dem växa i ett år eller två tills de nått full storlek."}, -- quests-batch-12-sv
[705]={t="Pärldykning", o="Lämna 9 blå pärlor till Rigglefuzz i Ofärdsmarken.", d="Ofärdsmarken är en hård plats, fylld med grymma rovdjur och djärva asätare. Skrämmande, särskilt för en liten kort gnom. För att överleva måste jag vara slug!$B$BJag kan receptet på blixtbomber. Jag använder dem för att skrämma bort vilda djur. Men jag börjar få slut på en av ingredienserna: krossat blått pärlpulver. Skaffa åt mig lite så ska jag se till att det lönar sig.$B$BHeh, och jag hoppas att du har bra stövlar på dig. De blå pärlorna jag behöver finns i musslor vid Vidrigrevet.$B$BJapp, Vidrigrevet i Strypetörnsdalen!"}, -- quests-batch-04-sv
[709]={t="Lösningen på undergången", o="Lämna Ryun'ehs tavla till Theldurin the Lost.", d="O herregud! O herregud! En undergång närmar sig. Märk mig! En undergång!$B$BNej, jag kan inte tala om det... kan inte uttala deras namn ifall de hör mig! Men om vi får veta, ja, om vi får veta mer om dem... då kan vi kanske lära oss hur vi stoppar dem!$B$BKanske.$B$BGå in i Uldaman. Nej! Jag sa det! Du måste hitta... hitta tavlan av... Ryun'eh. Ja, hitta den! Och få mig inte att uttala det namnet igen!$B$BDen finns djupt inne på den platsen, i en uråldrig kista. Det är där den gömmer sig... i en kista tillverkad före något dvärgarbete."}, -- quests-batch-08-sv
[712]={t="Studier av elementen: Sten", o="Lämna 5 Bracers of Rock Binding till Lotwil Veriatus i Ofärdsmarken.", d="$n, det finns ytterligare en del jag behöver från elementalen här i Ofärdsmarken: Bracers of Rock Binding från de större stenelementalerna. Enligt mina beräkningar bör dessa handledsskydd räcka för att mäta styrkan i mina egna bojor.$B$Bmina försök att spåna efter de större stenelementalerna visade en grupp av dem sydväst om här, nära några ograr om jag minns rätt.$B$BBring mig 5 av deras handledsskydd så att jag har extra. Servo är ökänd för att komma bort med mina reagenser och forskningsmaterial."}, -- quests-batch-10-sv
[713]={t="Kylmedelshuvuden segrar", o="Hitta frostolja och lämna den till Lotwil Veriatus i Ofärdsmarken.", d="Låt mig berätta något om frostolja: inget kan förhindra en motor eller kugghjul från att överhettas så effektivt som det.$B$BDess kylande egenskaper är extraordinära, och dess hållbarhet som smörjmedel är utan like. Det är inte allt: det hjälper även till att bevara förtrollningar på magiska föremål.$B$BJag behöver en flaska av det för att öka den magiska kapaciteten i mina bojor och göra dem kraftfulla nog att stoppa vår frammanade vän från att döda oss alla.$B$BBro'kin, en goblinvän till mig, kan lära dig att tillverka det. Han finns i Alterac."}, -- quests-batch-02-sv
[1048]={t="In i Scharlakansklostret", o="Döda High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion och Houndmaster Loksey och rapportera sedan tillbaka till Varimathras i Understaden.", d="Medan den mörka damen tar hand om den pressande frågan om Lichkungens frammarsch i norr, ser jag till att angelägenheter närmare hemmet tas om hand på ett tillbörligt sätt.$b$bUtan tvekan är de mänskliga skadedjuren som kallar sig Scharlakanskorståget den vassaste törnen i vår sida här hemma. Tirisfalgläntorna kryllar bokstavligen av små röda myror.$b$bRes till klostret, $c, och förgör High Inquisitor Whitemane och hennes främsta löjtnanter."}, -- quests-batch-06-sv
[1049]={t="De fallnas kompendium", o="Hämta De fallnas kompendium från klostret i Tirisfalgläntorna och återvänd till Sage Truthseeker i Dunderklippan.", d="Jordringen hade rena avsikter gentemot våra pestdrabbade bröder. Men vem kan veta motiven hos dem som viskar i Äldsterådets öron?$b$bDe bortglömda som vi har allierat oss med har en historia präglad av svek. Vårt pakt var alltför förhastad. Kanske hade Cairne varit klok i att lyssna på varningarna från Orgrimmar.$b$bDjupt inne i Scharlakansklostret ligger De fallnas kompendium, bevakat av galna mänskliga fanatiker. Deras metod är smidd av vansinne, men deras forskning kan visa sig vara användbar."}, -- quests-batch-11-sv
[1106]={t="Martek den landsförvisade", o="För Fizzles brev till Martek den landsförvisade i Ofärdsmarken.", d="Jag utvecklar en ny motor som kommer att få bilen att gå så snabbt! Snabbt nog att flyga, jag vet det! Jag behöver bara tillverka kolvar som tål mycket, mycket hög belastning. Alla mina försök har misslyckats eftersom jag inte kan göra kolvarna tillräckligt hårda!$B$BMen det finns någon som kanske vet hur.$B$BHans namn är Martek den landsförvisade. Han är en stor smed och vet mer om metall än någon annan. Ge honom det här brevet, jag vet att han kan hjälpa till!$B$BMen han är långt, långt borta -- i Azeroth, i Ofärdsmarken, i ett läger, med en gnom!$B$BHitta honom!"}, -- quests-batch-01-sv
[1107]={t="Inkrusterade stjärtfenor", o="För 10 inkrusterade stjärtfenor till Wizzle Brassbolts på Glittrande slätterna.", d="Vår raketbil är det snabbaste på slätterna! Så snabb att ... jag är rädd att friktionen kommer att slita isär den!$B$BFör att förhindra det behöver jag skapa ett kompositmaterial för att belägga bilens rörliga delar. Det måste vara hårt men inte sprött, och måste vara resistent mot saltkorrosion, annars kommer tiden på Glittrande slätterna att fräta bort det.$B$BHar du hört talas om Vidriga revet, $n? Det ligger utanför kusten av Stranglethorn Vale. Saltfjällsmurlocs lever där, och deras stjärtfenor är en avgörande ingrediens i mitt kompositmaterial."}, -- quests-batch-01-sv
[1109]={t="Går, går, guano!", o="Lämna 1 hög Kraulguano till mästerapotekare Faranell i Understaden.", d="Som du ser, $n, ägnar vi oss åt några mycket... intressanta experiment här vid det kungliga apotekarsällskapet.$b$bSom mästare här är det mitt jobb att övervaka våra mest ambitiösa alkemiska försök. Så mycket arbete och så lite tid!$b$bDu ser ut att ha rest mycket för att vara en $c. Kanske kan du hjälpa mig.$b$bJag behöver ett sällsynt ämne. Det är ett vidrigt material som kommer från en sällsynt art fladdermöss som bara finns i dynghålet känt som Knivkärrets snårskog. För med mig guanon från Kraulfladdermössen så att vi kan påbörja vårt arbete..."}, -- quests-batch-13-sv
[1112]={t="Delar till Kravel", o="Lämna Kravels delar till Kravel Koalbeard på Skimmerslätterna.", d="Här är Kravels paket, $n. Och när du levererar det, säg till honom... om han vill ha fler specialbeställningar får han betala sin skuld!"}, -- quests-batch-10-sv
[1113]={t="Ivrighetens hjärtan", o="Mästeralkemist Faranell i Undercity vill ha 20 ivrighetens hjärtan.", d="Varför jag behöver en sällsynt typ av guano, kan du fråga. Jo, för detta experiment vill jag se vilken effekt två diametralt motsatta kemiska substanser kan ha på varandra, särskilt när båda kombineras med ett ständigt toxiskt medel för att säkerställa de mest... fasansfulla resultaten.$b$bI de nordöstra topparna av Tirisfalgläntena ligger det Scharlakansklostret. Där samlas de galna lärjungarna av Scharlakanskorståget. Dräp dem och bringa mig deras ivriga hjärtan.$b$bVår blandning kommer att bli högst ondskefull!"}, -- quests-batch-01-sv
[1115]={t="Ryktesspridaren", o="Tala med Krazek i Bytesbukten.", d="Nu när vi har gjort en tjänst för gnomerna är det dags att göra goblinerna en tjänst! $B$BJag har hört att goblinracerpiloten Nazz Steamboil inte alltid använde det namnet. Jag undrar varför han ändrade det. Jag undrar om det är en hemlighet, och... jag undrar om han värderar den hemligheten.$B$BOm någon vet sanningen så är det Krazek i Bytesbukten, på den södra spetsen av Strypetörnsdalen. Tala med Krazek och fråga honom om vår goblinpilot.$B$BOm du kan få användbar information från honom, så kan vi kanske tjäna en slant på det."}, -- quests-batch-13-sv
[1147]={t="Svärmen växer", o="Döda 5 silitidssökare, 5 silitidskupdroner och 5 silitidsinvaderare och återvänd till Moktar Krin i Tusen nålar.", d="Hmm. Det verkar som om Belgrom anser att those monster är ett hot. Han vill att de ska drivas tillbaka till vilka djup som helst som de kröp upp ifrån.$B$BJag antar att det inte räckte med att döda dvärgarna som skickades av Upptäckarförbundet – nu måste jag skicka ett halvdött krigsparti in i ännu en strid. Vi kommer inte kunna göra det själva; inte i det här tillståndet. Utgrävningsplatsen ligger söder om här. Det borde inte finnas fler dvärgar att ta hand om. Känner du dig kapabel att svinga ett blad eller en stav och göra din del för att hjälpa oss?"}, -- quests-batch-03-sv
[1150]={t="Uthållighetstest", o="För Grenkas klo till Dorn Plainstalker i Tusen nålar.", d="Det gläder mig att se att ditt mod förblir orubbligt i ljuset av vad du redan har åstadkommit. Eftersom din tro är intakt är det dags att testa din kropp.$B$BFörst är ett uthållighetstest. Bege dig tillsammans med vänner till Roguefeather-lyan väster om Frivindsposten. Ta dig ner i djupen av deras tillhåll och förstör deras förråd. Då bör du ha provocerat deras vrede, och om du lyckas överleva tillräckligt länge kommer Grenka Bloodscreech själv efter dig – döda henne och bringa mig hennes klo för att slutföra ditt test."}, -- quests-batch-11-sv
[1151]={t="Styrkeprov", o="Ta med fragment av Rok'Alim till Dorn Plainstalker i Tusen nålar.", d="Under de gamla gudarnas tid bebod elementaler stora delar av denna värld. De tillbad de gamla gudarna, och gudarna höll elementalerna bundna till denna värld genom sin makt. När de gamla gudarna förvisades försvann elementalerna från vår värld och återvänder nu endast på befallning av kraftfulla magiker.$B$BDet finns dock undantag. Vissa elementaler var kraftfulla nog att stanna kvar här på egen hand. En sådan elemental är Rok'Alim.$B$BFör att testa din styrka, leta upp Rok'Alim i Tusen nålar och dräp honom."}, -- quests-batch-10-sv
[1160]={t="Kunskapsprov", o="Hitta The Beginnings of the Undead Threat och återlämna den till Parqual Fintallas i Undercity.", d="Jag ska berätta vad du måste söka, och jag kommer till och med att ställa min fråga, men inte för att du vill bevisa dig själv. Kunskap är långt viktigare än styrka. Även om andra verkar gå om dig i förmåga, kommer din kunskap om världen att vara mer värdefull.$B$BGå till klostret i norra Tirisfalgläntena. I biblioteket där finns en bok kallad Beginnings of the Undead Threat. Den användes av de nu korrupta paladinerna där för att träna dem att bekämpa mitt folk.$B$Bbringa den till mig"}, -- quests-batch-01-sv
[1182]={t="Goblin-sponsring", o="Lämna ritningarna för bränsleregulatorn till baron Revilgaz i Bytesbukten.", d="Hör här, Äventyrsbolagets shreddrar ute i Lake Nazferiti (i norra Strypetörnsdalen) har utrustats med en ny modell av bränsleregulator. Jag tänkte att Pozzik skulle kunna dra nytta av den om han kunde få tag på detaljerna. Tyvärr verkar Cozzle, förmannen där ute, vara lite smartare än jag gett honom kredit för.$b$bDu verkar dock ha större chans att hitta ritningarna. Jag vet att han förvarar dem i sitt hus, men de är nästan helt säkert inlåsta."}, -- quests-batch-12-sv
[1187]={t="Razzerics finjustering", o="Hämta Seaforium-boostern till Razzeric på Skimmerslätterna.", d="Pozzik är en fantastisk mekaniker, det vet jag, men han är rädd för att bara maxa eldkraften och hänga med på resan. Inte jag däremot.$b$bNär Pozzik är klar med en racer tar jag lite tid på mig för att göra mina egna modifieringar – du vet, lossa på kontrollerna, ta bort delar av ramen och tillsätta mer kraft!$b$bJag beställde en seaforium-booster från Shreev på Gizmorium i Gadgetzan, men tydligen kraschade zeppelinen den skickades med i Dammträsket! Jag måste ha den, $n!"}, -- quests-batch-11-sv
[1205]={t="Deadmire", o="För Deadmires tand till Melor i Åskbrunn.", d="Deadmire är en uråldrig krokodil i Dammvattensmyren. Och det är dags för honom att dö.$B$BOld gamla ben gnisslar när han drar sin enorma kropp genom träsket, och även om han fortfarande rör sig med ungdomens styrka och snabbhet, plågar hans åldrande kropp den stora anden inom honom, en ande vars låga inte kommer att vackla.$B$BMen nu lever han i ständig, vansinnig smärta. Du måste avsluta livet för denna ädla varelse, $n. Du måste leda Deadmire till frid."}, -- quests-batch-01-sv
[1361]={t="Regthar Deathgate", o="Tala med Regthar Deathgate.", d="En krigare av Horden, Regthar Deathgate, rekryterar agenter för ett uppdrag i landet Ödelandet. Tala med honom om du vill anmäla dig som frivillig. Han är stationerad i Kargmarkerna, i en serie bunkrar väster om Korsvägen.$B$BOch vässa dina vapen. Ödelandet är en plats sargad av krig."}, -- quests-batch-04-sv
[1362]={t="Kolkar i Ödelandet", o="Tala med Felgur Twocuts vid Spökvandrarposten i Ödelandet.", d="Kolkar-kentaurena lever i Ödelandet, och deras styrkor har spridit sig in i Kargmarkerna. Detta är ett känt faktum och vi har Horden-agenter som hanterar dem här.$B$BMen så länge kentaurena är starka i Ödelandet kommer de alltid att utgöra ett hot. Det är dags att vi gör oss av med det hotet.$B$BTala med Felgur Twocuts vid Spökvandrarposten i Ödelandet. Han skickades dit för att samla underrättelser om kentaurena. Han vet hur man bäst hanterar Kolkar i Ödelandet."}, -- quests-batch-10-sv
[1373]={t="Ongeku", o="Behåll ditt rykte hos Gelkis och lämna ett draenethyst-fragment till Uthek the Wise i Gelkis by i Ödelandet.", d="Du har mer att bevisa, och din nästa uppgift kommer att ta dig långt bort, så för tillfället kommer Gelkis att bekämpa Magram utan dig.$B$BJorden viskar många hemligheter till dem som lyssnar. En hemlighet jag hör handlar om en röd kristall. Den kallas draenethyst och är ny för vår jord. Den kommer från en plats där berg flyger och där demoner härskar.$B$Bbring mig ett fragment av draenethyst, så kommer det att göra min magi stark! Fragmentet finns på en plats som kallas Sorgeträsket, i händerna på den förlorade Ongeku."}, -- quests-batch-05-sv
[1429]={t="Den förvisade Atal'ai", o="Lämna knippet av Atal'ai-artefakter till den förvisade Atal'ai i Bakländerna.", d="Medan du trotsade farorna i Tårarnas pöl återvände en av mina spejare med en rulle skriven i blod på torkat kött. Det verkar vara en rättslig dom mot en präst från Atal'ai-stammen.$b$bDenna präst dömdes till ett öde värre än döden bland Atal'ai.$b$bHan förvisades för att leva långt i norr i Bakländerna, tillsammans med Vissenbark-trollen.$b$bJag kommer att knyta ihop dessa artefakter. Du ska söka upp den förvisade och upptäcka deras sanna användning. Återvänd till mig när din resa är fullbordad."}, -- quests-batch-04-sv
[1481]={t="Fördärvaren", o="Lämna en Shadowstalker-skalps till Maurin Bonesplitter i Ödelandet.", d="Jag tror att jag kan finna denna demonherre om jag har rätt reagenser.$B$BOm han verkligen är så kraftfull som jag misstänker, kommer jag att behöva föremål insamlade från dödliga varelser. Men du agerar i krigsledarens namn, så jag är säker på att du kommer att acceptera min uppgift.$B$BFörst måste jag bryta alla skydd han har mot spådom. För detta behöver jag skalpen från en satyr – men inte vilken satyr som helst. Skalpen måste komma från en Hatefury-skuggpirsare.$B$BSök efter dem bland de forna ruinerna i nordöstra Ödelandet."}, -- quests-batch-05-sv
[1482]={t="Den fördärvade", o="För med en orakelkristall till Maurin Bonesplitter i Ödelandet.", d="En orakelkristall skulle passa utmärkt. De tillverkas av naga för deras orakel att använda.$B$BNordväst härifrån, längs kusten, finns ett enormt korallrev som naga har gjort till sitt hem när de är så nära stranden. Du kan hitta deras orakel där. Slitherblade är dödliga och kommer inte att reagera vänligt på dina intrång, så var försiktig och skynda dig.$B$B", p="När du återvänder ska vi se till att hitta denna demonherre Azrethoc."}, -- quests-batch-14-sv
[1948]={t="Kraftföremål", o="För med dig 1 jade och den bultladdade törnen till Tabetha i Dammträsket.", d="Att tillverka en magikers trollstav är inte lätt. Sällsynta substanser krävs, och ett kärl måste skapas som kan lagra stora mängder magisk energi. Du måste samla dessa ting och föra dem till mig.$B$BJag har skrivit ner på detta pergament vad du behöver, samt instruktioner om hur du får tag på det. För med dig exakt det som står på listan och följ mina skrivna anvisningar till punkt och pricka, för om du inte gör det kan det gå... illa när vi tillverkar din stav."}, -- quests-batch-04-sv
[1949]={t="Dolda hemligheter", o="Tala med Magus Tirth på Skimmerslätterna.", d="För att tillverka din trollstav finns det nyckelavsnitt i en viss bok som jag måste läsa. Boken heter Rituals of Power och är skriven av Magus Tirth.$B$BJag har inget exemplar av hans bok, och inget av världens stora bibliotek äger den. Du måste därför tala med Tirth och få den av honom.$B$BLycka till. Tirth brukade vara en stor magiker och lärd, men nu tillbringar han sin tid vid gnom- och goblinloppen på Skimmerslätterna med att dricka och spela."}, -- quests-batch-07-sv
[1954]={t="Den infernala klotet", o="Lämna ett infernalt klot till Tabetha i Dammträsket.", d="Det första steget är att skaffa ett klot med kraft. Häxmästarna i Brinnande klingan har fina klot av hög kvalitet... det är synd att de har bundit demoner i dem! Men vi kan fixa det, ja det kan vi.$B$BGå till Ödelandet och ryck ett infernalt klot från en frammanare av Brinnande klingan. Du hittar frammanare vid Mannoroc-kulten.$B$BNär du har klotet, återvänd till mig."}, -- quests-batch-02-sv
[2202]={t="Uldaman-reagens", o="Lämna 12 magentafungisvampar till Jarkal Mossmeld i Kargath.", d="Jag har hört talas om en nyupptäckt växt som kallas magentafungisvampar. De växer i klungor djupt inne i utgrävningsplatsen i Uldaman; de kan finnas på andra ställen, men för tillfället är det den enda platsen jag vet att de finns på. Jag vill studera deras potentiella användning inom alkemi, och det är där du kommer in.$B$BHitta klungorna med magentahattar och ta med mig ett dussin hattar. Var varnad, klungorna kan spruta ut giftsporer om de skakas.$B$B", c="Gör detta för mig, så blandar jag ihop en sats av mina starkare läkande drycker till dig!"}, -- quests-batch-09-sv
[2342]={t="Återvunna skatter", o="Hämta Patrick Garretts familjeskatt från deras familjekista i den södra samlingshallen i Uldaman och bringa den till honom i Understaden.", d="Att sopa fladdermuskvalen med den här kvasten anstår inte en Garrett! Jag har tjänat några mynt på det här förbannade jobbet, och jag är villig att spendera dem på dig för att förbättra min situation.$B$BGarrettfamiljens föredragna vapen är inlåst i vår kista i den södra samlingshallen i Uldaman från den tid då vi Garretts slet där som grävare. Utan det kommer jag att sitta fast här för evigt - bokstavligen - och sopa upp efter dessa infernala fladdermöss.$B$BÅtervinn min familjs skatt och bringa den till mig! Hjälp mig att återställa mitt födelselod!"}, -- quests-batch-07-sv
[2418]={t="Kraftstenar", o="Lämna 8 kraftstenar från Dentrium och 8 kraftstenar från An'Alleum till Rigglefuzz i Ofärdsmarken.", d="För ett tag sedan hade jag en incident med mörkjärnsdvärgarna. De tog med mig till Angorfästningen för att studera två typer av märkliga stenar från Uldaman. Jag upptäckte att stenarna var hållbara och stabila kraftkällor om de behandlades på rätt sätt. Det är fantastiskt vad man kan hitta på den där gamla utgrävningsplatsen!$B$BAv och vidare, efter att jag berättat hemligheten om stenarna för dem kastade de ut mig från Angorfästningen och började gräva efter fler i Uldaman.$B$BJag vill ha those stenar själv! Hämta båda typerna så ska jag betala dig rikligt!"}, -- quests-batch-08-sv
[2752]={t="Om järnskulder", o="Lämna över fyra bronsstridsyxor och fyra bronskrigshammare till Orokk Omosh i Orgrimmar.", d="Orokk ser ivern i dina ögon, $n. Som en svamp suger du åt dig Omoshs visdom.$B$BTre lektioner ska jag lära dig!$B$BÅtervänd till städets hetta, känn smedjans glöd och skapa fyra bronsstridsyxor och fyra bronskrigshammare åt Orokk. Först då kommer du att lära dig om järnskuldern."}, -- quests-batch-13-sv
[2842]={t="Överingenjör Scooty", o="Tala med Scooty i Bytesbukten.", d="Så snart vi fick ord från Kernobee om den nya gnomiska riggen, började Scooty och jag arbeta på Transpolyporter 6000: det snabbaste och mest pålitliga sättet att ta sig till Gnomeregan.$B$BDen är äntligen redo för passagerare, $n. Om du vill prova den, bege dig till Bytesbukten och tala med Scooty vid vindryttarnas utpost. För att komma till Bytesbukten, ta båten från Spärrhake.$B$BSjälvklart kan du alltid försöka ta dig till Gnomeregan genom de dvärginfesterade bergen i Dun Morogh!"}, -- quests-batch-13-sv
[2861]={t="Tabethas uppdrag", o="Tala med Tabetha i Dammträsket.", d="Ryktet säger att Tabetha, en magikerkollega som bor djupt inne i Dammträsket, har ett gammalt räkenskap att göra upp med en viss sandtroll i Zul'Farrak. Om du talar med Tabetha kan hon berätta mer.$B$BOch ta med dig några vänner, $n. Om Tabetha ber dig bege dig till Zul'Farrak kommer du inte vilja gå dit ensam.$B$BDu hittar Tabethas stuga väster om Theramore, precis norr om Stonemaul Ruin."}, -- quests-batch-06-sv
[2932]={t="Dystert budskap", o="Samla Vissenbarkskallar och placera dem på Nimboyas pik. Placera Nimboyas tyngda pik i en av Vissenbarksbyn i Bakländerna, och återvänd sedan till Nimboya i Strypetörnsdalen.", d="Vissenbarkstrollen var en gång allierade med Horden, men de förrådde Thrall... och det måste straffas!$B$BHär, ta min pik och bege dig till Bakländerna, långt i norr. Du finner det nordost om Tarrens kvarn, en by som hålls av våra allierade, De bortglömda.$B$BNär du når Bakländerna, jaga vissenbarkstroll. Samla deras skallar och driv ner min pik i marken i en av deras mindre byar, Hiri'watha eller Zun'watha.$B$BVisa dem att deras avskyvärda handlingar får konsekvenser!", p="Placera det dystra budskapet."}, -- quests-batch-04-sv
[2945]={t="Smutsig ring", o="Hitta ett sätt att få bort smutsen från den smutsiga ringen.", d="Du har hittat vad som ser ut att vara en ring från liket av en av mörkjärnsdvärgarna. Det är dock svårt att avgöra vilken sorts ring det är; smuts och härdade rester täcker föremålet helt, vilket gör det omöjligt att bära. Du tror att du kan ana en svag glans av ädelmetall och kanske till och med skimret av en ädelsten under resterna.$B$BOm du ska kunna använda den här ringen måste du hitta något som kan få bort de härdade resterna från den."}, -- quests-batch-13-sv
[2949]={t="Ringens återkomst", o="Du kan antingen behålla ringen, eller så kan du försöka hitta personen som är ansvarig för avtrycket och gravyrerna på insidan av ringen.", d="När du öppnar asken som skapades av Sparklematic 5200 avslöjas en glänsande ring! När du tar på dig ringen känner du hur magisk kraft strömmar genom din kropp.$B$BPå insidan av ringen finns ett litet men ändå tydligt avtryck av Orgrimmars sigill. Bredvid det finns graverade bokstäver, men endast de tre första är läsbara även efter rengöring: \"NOG...\"$B$BDetta kan antingen vara den tidigare ägarens initialer, eller kanske initialerna för ringens smed. Behåll ringen... eller leta efter \"NOG\" - svåra beslut..."}, -- quests-batch-05-sv
[3341]={t="Bringa slutet", o="Andrew Brownell vill att du dödar Amnennar den kalla och återlämnar hans skalle.", d="I Barrens ligger ett fasansfullt kaos av sammanflätade rankor kallat Razorfen Downs. Medan våra första observationer av denna plats avslöjade lite hot, är våra senaste fynd mycket mer allvarliga...$B$BQuilboarna i Razorfen Downs har allierat sig med pestan. En lich vid namn Amnennar den kalla styr dem nu, och använder kraften i sitt massiva medvetande för att kontrollera varje rörelse de gör.$B$BAmnennar har en direkt telepatisk länk till Ner'zhul; vi måste bryta detta band, $n. Ett slut måste komma för den kalla."}, -- quests-batch-01-sv
[5386]={t="Dagens fångst", o="Tala med Jinar'Zillen i Skuggbytesbyn och lämna sedan 2 blodmagfiskar till Nataka Longhorn.", d="Doften av stekt fisk har saknats här vid Spökvandrarposten under lång tid. Trollen i Skuggbytesbyn är bäst på att fånga fisk... men tyvärr, med all kentaurens aktivitet har jag lite tid att göra en resa till trollen. Hrm...$B$BGör mig en tjänst och res till Skuggbytesbyn. Tala med den lokale fiskaren Jinar'Zillen och ta med min favorit, blodmagfisk, tillbaka till mig. Vägen söderut härifrån leder dig västerut till trollbyn."}, -- quests-batch-13-sv
[5762]={t="Hemet Nesingwary", o="För med dig Kravels låda till Hemet Nesingwary i Strypetörnsdalen.", d="Jag har ett paket till en gammal kund, en dvärg vid namn Hemet Nesingwary. Paketet tog veckor att anlända, och Hemet är för länge sedan borta. Han sa att han skulle till Strypetörnsdalen för att jaga djuren där, men han lämnade mig pengar för att skicka leveransen när jag kunde. $B$BHemet är en rik dvärg och det är en god idé att hålla kontakten med de rika, eller hur? Så... vill du leverera paketet åt mig?$B$BJag har hört att Hemet har ett läger i Strypetörnsdalen, norr om Grom'gol."}, -- quests-batch-04-sv
[5763]={t="Jakten i Strypetörnsdalen", o="För Roons kodohorn till Hemet Nesingwary i Strypetörnsdalen.", d="För länge sedan kom en dvärg till det här landet. Hans namn var Hemet och han önskade jaga stora odjur. Hans skicklighet med geväret var häpnadsväckande, och vi tillbringade många dagar med att jaga tillsammans. Även fiendskapen mellan våra folk glömdes.$B$BNär han lämnade Ödelandet för Strypetörnsdalen, svor jag på att en dag välkomna honom tillbaka så att vi kan jaga igen. Nu är den tiden.$B$BTa med det här kodohornet till Hemet. Han kommer att förstå att det är från mig. Du hittar honom i Strypetörnsdalen, norr om Grom'gol-baslägret."}, -- quests-batch-07-sv
[6134]={p="Jag har en stark misstanke om att Magram är MYCKET intresserade av det här kletet. Jag planerar att sälja det till dem."}, -- quests-batch-05-sv
[6142]={t="Betesmusslor", o="Hitta 10 bitar mjukskalig musselkött och ta dem till Mai'Lahii i Skuggbytesbyn.", d="Du ser ut som en fiskare, $c! Jag älskar att fiska - har fiskat hela mitt liv. Det bästa betet man kan använda är mjukskaligt musselkött; fiskarna kan helt enkelt inte motstå det, du förstår vad jag menar?$B$BLängre norrut kommer du att hitta ett vrak utanför kusten. Mjukskaliga musslor ligger strödda över hela området. Om du tar med mig 10 bitar mjukskaligt musselkött ska jag ge dig något i utbyte."}, -- quests-batch-10-sv
[6143]={t="Andra fiskar att steka", o="Dräp 7 Slitherblade-myrmidoner, 7 Slitherblade-naga och 5 Slitherblade-trollkvinnor, och tala sedan med Drulzegar i Shadowprey i Desolace.", d="Kanske har du hört eller kanske inte... mitt besättning och jag var ute och fiskade nära Ranazjar Isle, norr om det vrakade skeppet utanför kusten i norr. Vi brukade fiska där hela tiden; nu tänker jag bara på ett sätt att hämnas mina fallna kamrater.$B$BNagan attackerade oss en morgon och dödade alla utom mig.$B$BMitt samvete kan inte hantera skulden, $c; jag behöver att du går och steker those naga åt mig. Jag ska se till att ansträngningen är värd din tid; tror du att du kan hjälpa mig med det?"}, -- quests-batch-01-sv
[6521]={t="En ohelig allians", o="För med dig ambassadör Malcins huvud till Varimathras i Understaden.", d="Malcin påstår att han befinner sig utanför Knivkärrets kullar. Denna ambassadör måste dödas – hans uppdrag är ett misslyckande i Lichkungens ögon.$B$BHans närvaro där förklarar mycket av det vi upptäckt om området – vissa av piggsvinsfolket har blivit skrämmande kraftfulla samtidigt som de visar tecken på pesten på sitt eget sätt. Det måste sannerligen vara ett tecken på någon sorts överenskommelse de har slutit.$B$BHitta Malcin och dräp honom, $n. Återvänd till mig när dådet är utfört."}, -- quests-batch-09-sv
[6610]={t="Musslovertärta", o="Dirge Quikcleave vill att du hämtar följande föremål:$B$B12 jätteägg. Du hittar dessa hos rokar som vandrar i Tanaris eller hos andra stora fågelarter.$B$B10 bitar smakrik musselkött. De hittas i musslor, naturligtvis!$B$B20 bitar Alterac-schweizer. Bege dig till ett mejerier!$B$BSamla alla föremål och återvänd till Dirge.", d="Har du någonsin hört talas om en musslovertärta? Självklart har du inte det! Det är mitt senaste och främsta kulinariska mästerverk. Åh, $n, bara tanken på en musslovertärta får mig att dregla.$B$BTyvärr har jag slut på ingredienser för att göra någon! Hur om vi gör en deal? Du samlar ingredienserna jag behöver för att göra en musslovertärta, så ska jag lära dig de finare detaljerna i exotisk kokkonst och jag slänger till och med med ett par musslovertärter på köpet! Deal??$B$BHär är vad jag behöver:"}, -- quests-batch-09-sv
[7067]={t="Pariarens instruktioner", o="Läs pariarens instruktioner. Hämta sedan Unionens amulett från Maraudon och lämna tillbaka den till kentaureparianen i södra Ödelandet.", d="Trots att jag är förvisad som kättare är min tro fortfarande sann – det är det som driver mig framåt. Men för att mitt öde ska fullbordas behöver jag hjälp från en utomstående... någon som inte tillhör någon kentaurstam.$B$BUppgiften kräver att någon går in i Maraudons heliga hallar – en grav som mitt folk skyddar, och där endast de mest hängivna någonsin tillåts träda in.$B$BOm du går med på att hjälpa mig behöver du bara nicka. Jag ska ge dig ett pergament med mina instruktioner. Läs igenom det och fundera över mina ord."}, -- quests-batch-09-sv
[7321]={t="Lugnande sköldpaddssoppa", o="Lämna 10 stycken sköldpaddskött och lite lugnande kryddor till Christoph Jeffcoat i Tarrens kvarn.", d="Vem säger att de odöda inte kan någonting om matlagning? Ta mitt hemliga recept på sköldpaddssoppa som exempel. Jag har känt folk som skulle ha återvänt från döden bara för att njuta av en skål! Heh, heh...$B$BPå tal om det, jag har inte kunnat laga någon på sistone. Jag brukade själv bege mig till Lordameresjön för att jaga snapjaws, those nasty things, men jag kan inte slita mig loss från mitt arbete här.$B$BOm du hämtar lite sköldpaddskött från snapjaws och lugnande kryddor, ska jag visa dig hur det går till!"}, -- quests-batch-06-sv
[8551]={t="Kaptenens kista", o="Lämna Smotts kista till Hecklebury Smotts i Bytesbukten.", d="Jag brukade segla ett skepp härifrån hela vägen till Spärrhake i Kalimdor. Jag var en framgångsrik kapten med ett oklanderligt rykte.$B$BTills...$B$BDessa förbannade havsjättar ruinerade mig! De krossade mitt skepp, dödade min besättning och satte mig i en livbåt till Bytesbukten. Och en av jättarna, Gorlash, stal min kaptenskista. Han sa att han ville ha den som en snusdosa. Vilket vågspel!$B$BJag har hört att Gorlash vandrar längs kusten öster om här. Hitta honom och hämta min kista! Gör det, så har du förtjänat en kaptens tacksamhet."}, -- quests-batch-08-sv
[79361]={o="Ta den här tomeboken. Den var avsedd för studier, men kan nu inneha nyckeln till att skingra den kommande stormen."}, -- quests-batch-03-sv
[79677]={o="Skonk kan laga mat, men behöver ingredienser. Du skriver upp. Hitta ingredienser. Skonk mer fokuserad på själva lagningen; inte riktigt en logistikkille."}, -- quests-batch-03-sv
[86576]={o="Medan du bekämpar harpyorna i dalen, håll utkik efter glittrande solstenar. Ta alla du hittar till Mor'rogal, uppe på kullarna ovanför oss."}, -- quests-batch-09-sv
[92401]={o="Det finns saker där som jag inte kan hantera, men om du är villig behöver jag få veta vad som hänt min make.", d="Undersök försvinnandet av Edward Heartweaver i Lordaerons ruiner."}, -- quests-batch-05-sv
[92421]={o="Om vår ärorika kapten Garek Bandarion fortfarande hade varit med oss, så vet jag vad han hade önskat. Att slutföra det han påbörjade och hela våra fränder. För Lordaeron!"}, -- quests-batch-07-sv
[92519]={p="Följ vägen till Go'shek farm, söderut och en bit väster om här. Du kommer troligen att finna den packad och redo att ge sig av, med Jorell antingen försvunnen eller likgiltig inför sina förpliktelser."}, -- quests-batch-06-sv
[92743]={p="Gör detta för mig, så ska jag avslöja Magrams största styrka."}, -- quests-batch-08-sv
[93225]={o="Jag tror att vi kan vända striden till vår fördel med antingen Gelkis eller Magram om vi levererar ett tungt knippe totemer direkt till dem. Jag har redan börjat tälja några, men jag tvivlar på att de låter sig luras så lätt utan några äkta."}, -- quests-batch-12-sv
[93429]={d="Deras lidande måste ta slut. Någon måste befria dem från deras misär. En makaber uppgift, jag vet, men skulle du göra det för att skydda oss som är kvar?"}, -- quests-batch-01-sv
[93464]={o="Jag ber dig att finna denna magiker, $r. Hans kunskap skulle kunna vara av enormt värde för oss."}, -- quests-batch-12-sv
[93663]={o="Viktigare är att mitt rykte i affärsvärlden står på spel. Den sändningen måste hittas och levereras till hamnen. Snälla, hitta den om du kan. Leta vid vattnet längs vägen."}, -- quests-batch-09-sv
[93678]={p="Även om mina svar inte är definitiva, ta gärna med dig dessa anteckningar tillbaka till träsket. Jag hoppas att du förstår varför jag inte följer med."}, -- quests-batch-11-sv
[93680]={o="Sök efter något i deras läger som kan hjälpa oss att ta oss in i staden obemärkt. Jag måste få veta mer."}, -- quests-batch-02-sv
[93976]={d="Ta det här. När du lämnar över det, låt henne veta att jag skickade dig. Och säg åt henne att vi är kvitt."}, -- quests-batch-04-sv
[94220]={t="Hantverksorder: Dolk med pärlhandtag", o="Skaffa föremålen som kunden begärt och leverera dem till platsen markerad på din karta. Denna order måste vara i din ägo för att slutföra transaktionen.", d="<Skrivet med blekt bläck begär noten en $2oa dolk med pärlhandtag, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order är överförbar.>"}, -- quests-batch-01-sv
[94221]={t="Hantverksorder: Guldstav", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Guldstav, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-07-sv
[94239]={t="Hantverksorder: Fina läderbyxor", o="Skaffa föremålen som kunden begärt och leverera dem till platsen som är markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär lappen $2oa Fina läderbyxor, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-10-sv
[94251]={t="Hantverksorder: Fenixbyxor", o="Skaffa föremålen som kunden begärt och leverera dem till platsen markerad på din karta. Denna order måste finnas i din ägo för att transaktionen ska kunna slutföras.", d="<Skrivet med blekt bläck begär noten $2oa Fenixbyxor, tillsammans med information om leveransplats och betalning. Längst ner finns text som anger att denna order kan överföras.>"}, -- quests-batch-09-sv
[94481]={o="Ta det här och mata våra rekryter i väster. Lyssna inte på några klagomål. Med tanke på hur svårt det har blivit att försvara våra försörjningslinjer bör de vara tacksamma att vi inte matar dem med jord."}, -- quests-batch-05-sv
[94532]={o="Röj en väg för våra allierade genom att eliminera hotet."}, -- quests-batch-03-sv
[94535]={p="Res söderut, lokalisera deras läger och hämta den stulna malmen. Ta den från deras döda kroppar om det behövs."}, -- quests-batch-13-sv
[95162]={o="Om vi ska ha tillräckligt med kött till Rog'mar behöver jag din hjälp med skörden."}, -- quests-batch-07-sv
[95163]={o="Några av de små har rymt över floden. De är fortfarande för små för att skördas ute på fältet, så vi måste föra tillbaka dem hit. Ta den här pinnen och ge dem en rejäl smäll! Det borde få dem att skuttra tillbaka till sina hagar."}, -- quests-batch-06-sv
[95261]={o="Hallå! Sluta stå och glo! Jag behöver inälvor, JÄTTEMYCKET av dem. Vilket djur som helst härifrån. Ju stinkigare <hic> desto bättre. Jag behöver också några ruttnelsskivlingar. De växer i den där grottan vid Windstead."}, -- quests-batch-07-sv
[95534]={d="< Resten av anteckningen är svedd och sönderriven, som om den bränts av eldmagi. >"}, -- quests-batch-02-sv
[95775]={o="Gå in i ruinerna och samla avritningar av alla tavlor du hittar där, återvänd sedan till mig."}, -- quests-batch-13-sv
[95951]={o="Först ska du få egna spjut. Det här är mitt. Gå till människlägret i väster och ta deras trä. Ta med en kniv. Du kan vässa deras timmer till bra spjut för att sticka med. Sen tar du med dem tillbaka."}, -- quests-batch-12-sv
[95955]={o="Gå och sätt i dig en massa av dem. Sen kommer du tillbaka till gamle Tran'jani för ditt pris. Om du kan sätta i en krokolisk kan du sätta i vad som helst."}, -- quests-batch-09-sv
[95982]={c="Om du inte kan tillverka det själv, kanske någon är villig att sälja lite till dig. Och skynda dig! Det sista jag behöver är en stampad av hungriga djur."}, -- quests-batch-08-sv
[96063]={o="Om du känner för att göra ett ödmjukt bidrag till vetenskapens och industrins framtid, varför hjälper du mig inte att få tag på lite av den där gasen? Du kan se den stiga upp från ventilerna nära vattnet."}, -- quests-batch-12-sv
[96105]={d="Jag önskar dig lycka till i din jakt. Må du återvända i ära."}, -- quests-batch-04-sv
[96222]={p="Ta med nyckeln till mig, så har jag ett förslag till dig."}, -- quests-batch-10-sv
[96774]={p="Gamle Mazu'kon skulle gärna vilja få tag på en av dessa idoler... för akademins skull, ser du. Hur med att du samlar några vänner och kör lite \"krossa och sno\" i den där drunknade staden som sticker upp ur havet utanför kusten vid Strypetörnsdalen? Döda den mest imponerande prästen du kan hitta där inne, så har de säkert det jag letar efter."}, -- quests-batch-10-sv
[96781]={o="Om du hoppas finna honom är han troligtvis bland Syndikatet i Strahnbrad."}, -- quests-batch-11-sv
[96783]={o="För att infiltrera fästet utan att väcka misstankar behöver du en förklädnad. Se om du kan hitta en hos Syndikatet utanför fästet, vid Northfold Manor."}, -- quests-batch-02-sv
[96986]={o="Jag bryr mig inte om magikerstadens öde, $n, men denna gravriddare spottar i ansiktet på allt vi De bortglömda står för. Gör slut på honom. Visa honom att ingen är utom räckhåll för den mörka damen."}, -- quests-batch-12-sv
[96988]={p="Gå till staden och leta reda på konstruktens kärnor. Det är osannolikt att de ger upp dem frivilligt, så gör vad som krävs."}, -- quests-batch-11-sv
[97196]={o="Gå in i Knivkärrets kullar till Amnennar the Coldbringers näste och hämta orben känd som Coldbringer's Eye åt mig."}, -- quests-batch-03-sv
[97200]={o="Tala med mig när du har tillräckligt med guld, så ska jag lära dig att rida raptor."}, -- quests-batch-03-sv
[97265]={o="Nu vill jag ha hämnd. Hämnd mot Hatraseri. Storma deras läger i nordost! Fläcka marken med deras vidriga blod."}, -- quests-batch-02-sv
[97287]={o="Ta den partikel du fick. De kommer säkert att ge vad som helst för att få tillbaka den. Vad som helst."}, -- quests-batch-03-sv
[97386]={o="Samla en vän eller två och gör det väldigt tydligt att vi inte kommer att tolerera ytterligare hot mot vår bosättning, varken nu eller någonsin!"}, -- quests-batch-07-sv
[97453]={o="Jag sprang iväg och jag mår bra, men nu låter de mig inte leka utanför lägret längre. Kan du göra det säkert för mig, och sedan berätta för min mamma?"}, -- quests-batch-06-sv
[97539]={o="$C, hämta några från spindlarna som jagar i dessa högland."}, -- quests-batch-08-sv
[97663]={o="Nu är jag helt slut på förnödenheter och saknar studiematerial medan jag återhämtar mig. Kan du bege dig österut för att leta efter min packning och själv göra avritningar av ristningarna?"}, -- quests-batch-02-sv
[97985]={p="Åh, jag föreslår även att du tar med dig vänner. Stormheart är inte känd för att vara foglig."}, -- quests-batch-02-sv
[98069]={o="Jag är inte säker på vad harpyorna planerar att göra med de extra förnödenheterna, men jag skulle vara tacksam om du återhämtade dem åt mig. De har sitt läger väster om här. De kan hittas både vid foten av klippan och inne i en grotta på toppen."}, -- quests-batch-03-sv
[98070]={p="Gå, dräp så många av dessa harpyor du kan. Återvänd till mig när dådet är utfört, så ska jag belöna dig väl för dina ansträngningar."}, -- quests-batch-14-sv
[98248]={d="Bredvid texten finns en grovt ritad karta över området nära den ovannämnda destinationen.>"}, -- quests-batch-07-sv
}

for id, add in pairs(extra) do
    if LQ[id] == nil then LQ[id] = add end   -- skriv aldrig over granskat innehll
end
